package org.example.phonecontroller;
import java.nio.ByteBuffer;
import java.util.*;
public final class LocalRegionStabilityTest {
 static final String S="capture-1/task-1";
 static void ok(boolean b,String m){if(!b)throw new AssertionError(m);}
 static LocalRegionStability.Target t(String text,int x){return new LocalRegionStability.Target("skip",text,"skip",x,20,x+20,40);}
 static LocalRegionStability tracker(){LocalRegionStability r=new LocalRegionStability();r.configure(S,100,100,Arrays.asList(t("跳过",20)));return r;}
 static ByteBuffer image(){ByteBuffer b=ByteBuffer.allocate(100*100*4);for(int i=0;i<b.capacity();i+=4){b.put(i,(byte)80);b.put(i+1,(byte)90);b.put(i+2,(byte)100);b.put(i+3,(byte)255);}return b;}
 static LocalRegionStability.Snapshot frame(LocalRegionStability r,ByteBuffer b,long n){return r.observe(S,n,1_000_000_000L+n*80_000_000L,b,100,100,4,400);}
 static LocalRegionStability.Region region(LocalRegionStability.Snapshot s){ok(s.valid,"expected valid source observation");return s.regions.get(0);}
 static void tenFrames(){LocalRegionStability r=tracker();ByteBuffer b=image();for(int i=1;i<=9;i++)ok(!region(frame(r,b,i)).ready,"before ten");LocalRegionStability.Region x=region(frame(r,b,10));ok(x.ready&&x.count==10&&x.stableMs==720,"ten real same-pixel frames should be ready");}
 static void dynamicOutside(){LocalRegionStability r=tracker();ByteBuffer b=image();for(int i=1;i<=10;i++){for(int y=60;y<100;y++)for(int x=0;x<100;x++)b.put(y*400+x*4,(byte)i);frame(r,b,i);}ok(r.snapshotAt(1_800_000_000L).regions.get(0).ready,"outside video must not reset");}
 static void targetChange(){LocalRegionStability r=tracker();ByteBuffer b=image();for(int i=1;i<=10;i++)frame(r,b,i);b.put(30*400+30*4,(byte)44);ok(region(frame(r,b,11)).count==1,"target pixel reset");}
 static void surroundingChange(){LocalRegionStability r=tracker();ByteBuffer b=image();for(int i=1;i<=10;i++)frame(r,b,i);for(int y=17;y<20;y++)for(int x=17;x<43;x++)b.put(y*400+x*4,(byte)1);ok(region(frame(r,b,11)).count==1,"surrounding pixels reset");}
 static void duplicates(){LocalRegionStability r=tracker();ByteBuffer b=image();LocalRegionStability.Snapshot first=frame(r,b,1);for(int i=0;i<20;i++){LocalRegionStability.Snapshot s=frame(r,b,1);ok(!s.valid,"duplicate must not emit new report");}ok(r.snapshotAt(first.sourceTimestampNs).regions.get(0).count==1,"duplicate cannot increment original");ok(region(frame(r,b,2)).count==2,"duplicate must not reset");ok(!r.observe(S,3,1_160_000_000L,b,100,100,4,400).valid,"duplicate timestamp");ok(region(frame(r,b,3)).count==3,"timestamp duplicate ignored");}
 static void fastFrames(){LocalRegionStability r=tracker();ByteBuffer b=image();for(int i=1;i<=10;i++)ok(!region(r.observe(S,i,1_000_000_000L+i*10_000_000L,b,100,100,4,400)).ready,"ten frames faster than 600ms");}
 static void gapAndOrder(){LocalRegionStability r=tracker();ByteBuffer b=image();frame(r,b,1);frame(r,b,2);ok(region(r.observe(S,3,1_500_000_000L,b,100,100,4,400)).count==1,"gap reset");ok(!frame(r,b,1).valid,"reversed source invalid");ok(region(r.observe(S,4,1_580_000_000L,b,100,100,4,400)).count==1,"reversed clears counts without lowering high water mark");}
 static void epochs(){LocalRegionStability r=tracker();ByteBuffer b=image();for(int i=1;i<=10;i++)frame(r,b,i);r.configure("capture-2/task-2",100,100,Arrays.asList(t("跳过",20)));ok(r.snapshotAt(1_800_000_000L)==null,"epoch clears old ring");ok(region(r.observe("capture-2/task-2",1,1,b,100,100,4,400)).count==1,"epoch reset");ok(!r.observe(S,11,2,b,100,100,4,400).valid,"stale scope rejected");}
 static void geometry(){LocalRegionStability r=tracker();ByteBuffer b=image();frame(r,b,1);frame(r,b,2);ByteBuffer large=ByteBuffer.allocate(200*100*4);LocalRegionStability.Region x=region(r.observe(S,3,1_240_000_000L,large,200,100,4,800));ok(x.count==1&&x.physicalLeft==40&&x.physicalRight==80,"physical geometry maps/reset");ok(r.snapshotAt(1_080_000_000L)==null,"geometry clears ring");r.configure(S,200,100,Arrays.asList(t("跳过",20)));ok(region(r.observe(S,4,1_320_000_000L,large,200,100,4,800)).count==1,"screenshot geometry resets");}
 static void jitterAndLost(){LocalRegionStability r=tracker();ByteBuffer b=image();for(int i=1;i<=10;i++)frame(r,b,i);r.configure(S,100,100,Arrays.asList(t("跳过",23)));LocalRegionStability.Region x=region(frame(r,b,11));ok(x.ready&&x.left==20&&x.count==11,"3px jitter retains ORIGINAL ROI");r.configure(S,100,100,Arrays.asList(t("跳过",24)));ok(region(frame(r,b,12)).count==1,"larger shift resets");r.configure(S,100,100,Arrays.asList(t("关闭",24)));ok(region(frame(r,b,13)).count==1,"label change resets");r.configure(S,100,100,Collections.emptyList());ok(frame(r,b,14).regions.isEmpty(),"lost target removed");ok(r.snapshotAt(1_000_000_000L+13*80_000_000L)!=null,"lost target preserves original source history");}
 static void snapshots(){LocalRegionStability r=tracker();ByteBuffer b=image();LocalRegionStability.Snapshot old=frame(r,b,1);for(int i=2;i<=10;i++)frame(r,b,i);ok(r.snapshotAt(old.sourceTimestampNs)==old&&old.regions.get(0).count==1&&!old.regions.get(0).ready,"old source cannot gain future stability");try{old.regions.clear();throw new AssertionError("snapshot mutable");}catch(UnsupportedOperationException expected){}for(int i=11;i<=40;i++)frame(r,b,i);ok(r.snapshotAt(old.sourceTimestampNs)==null,"ring evicts beyond32");ok(r.snapshotAt(1_000_000_000L+9*80_000_000L)!=null,"ring retains32");}
 static void invalidBuffers(){LocalRegionStability r=tracker();ByteBuffer b=image();for(int i=1;i<=10;i++)frame(r,b,i);ByteBuffer shortB=ByteBuffer.allocate(39999);ok(!r.observe(S,11,1_880_000_000L,shortB,100,100,4,400).valid,"short buffer rejected");ok(r.snapshotAt(1_800_000_000L)==null,"invalid cannot leave ready history");ok(region(frame(r,b,12)).count==1,"invalid resets");ok(!r.observe(S,13,2_040_000_000L,b,100,100,3,400).valid,"bad pixelStride");ok(!r.observe(S,14,2_120_000_000L,b,100,100,4,399).valid,"overlap row");ok(!r.observe(S,15,2_200_000_000L,b,Integer.MAX_VALUE,100,4,Integer.MAX_VALUE).valid,"overflow geometry");}
 static void alphaAndPosition(){LocalRegionStability r=tracker();ByteBuffer b=image();for(int i=1;i<=10;i++){for(int j=3;j<b.capacity();j+=4)b.put(j,(byte)i);frame(r,b,i);}ok(r.snapshotAt(1_800_000_000L).regions.get(0).ready,"alpha ignored");ByteBuffer padded=ByteBuffer.allocate(9+100*420);padded.position(9);LocalRegionStability p=tracker();int pos=padded.position();ok(p.observe(S,1,1,padded.asReadOnlyBuffer(),100,100,4,420).valid,"position/padded rows accepted");ok(padded.position()==pos,"position unchanged");}
 static void limits(){LocalRegionStability r=tracker();List<LocalRegionStability.Target> ts=new ArrayList<>();for(int i=0;i<65;i++)ts.add(new LocalRegionStability.Target("id"+i,"t","button",1,1,2,2));try{r.configure(S,100,100,ts);throw new AssertionError("65 accepted");}catch(IllegalArgumentException expected){}ok(!frame(r,image(),1).valid,"invalid config fails closed");}

 static void exactDuration(){LocalRegionStability r=tracker();ByteBuffer b=image();for(int i=1;i<=9;i++)r.observe(S,i,1_000_000_000L+(i-1)*60_000_000L,b,100,100,4,400);ok(!region(r.observe(S,10,1_599_999_999L,b,100,100,4,400)).ready,"599.999999ms not ready");ok(region(r.observe(S,11,1_600_000_000L,b,100,100,4,400)).ready,"600ms inclusive");}
 static void retainedHistory(){LocalRegionStability r=tracker();ByteBuffer b=image();LocalRegionStability.Snapshot old=frame(r,b,1);r.configure(S,100,100,Arrays.asList(t("跳过",22)));ok(r.snapshotAt(old.sourceTimestampNs)==old,"equivalent config must retain ring for async OCR");ok(region(frame(r,b,2)).count==2,"equivalent config retains count");r.configure(S,100,100,Arrays.asList(new LocalRegionStability.Target("skip","跳过","close",20,20,40,40)));ok(region(frame(r,b,3)).count==1,"role change resets");}
 static void edgeAndStride(){LocalRegionStability r=new LocalRegionStability();r.configure(S,100,100,Arrays.asList(new LocalRegionStability.Target("edge","x","close",0,0,100,100)));ByteBuffer b=ByteBuffer.allocateDirect(100*808+7);b.position(7);ok(r.observe(S,1,1,b.asReadOnlyBuffer(),100,100,8,808).valid,"nonstandard pixelStride and clamped surroundings");ok(b.position()==7,"read-only buffer position retained");ByteBuffer limited=ByteBuffer.allocate(40000);limited.limit(39999);ok(!r.observe(S,2,2,limited,100,100,4,400).valid,"limit not capacity governs safety");}
 static void invalidConfig(){LocalRegionStability r=tracker();ByteBuffer b=image();frame(r,b,1);try{r.configure(S,100,100,Arrays.asList(t("x",20),t("x",21)));throw new AssertionError("duplicate id allowed");}catch(IllegalArgumentException expected){}ok(!frame(r,b,2).valid,"duplicate configuration invalidates old state");r=tracker();try{r.configure(S,100,100,Arrays.asList(new LocalRegionStability.Target("bad","x","close",99,0,101,2)));throw new AssertionError("outside bounds accepted");}catch(IllegalArgumentException expected){}ok(r.snapshotAt(1)==null,"bad geometry clears ring");}
 static void clearAndNull(){LocalRegionStability r=tracker();ByteBuffer b=image();frame(r,b,1);r.clear();ok(!frame(r,b,2).valid,"explicit clear ends observations");r=tracker();ok(!r.observe(S,1,1,null,100,100,4,400).valid,"null buffer rejected");ok(region(frame(r,b,2)).count==1,"null does not leave ready data");}


 static void asynchronousConfiguration(){
   LocalRegionStability r=tracker();ByteBuffer b=image();LocalRegionStability.Snapshot a=null;
   for(int i=1;i<=10;i++)a=frame(r,b,i);
   long captured=a.sourceTimestampNs;
   r.configure(S,100,100,Arrays.asList(t("跳过",20),new LocalRegionStability.Target("req-new-1","x","close",60,20,80,40)));
   ok(r.snapshotAt(captured)==a,"async old frame must survive unrelated target addition");
   ok(a.regions.size()==1&&a.regions.get(0).id.equals("skip")&&a.sourceTimestampNs==captured&&a.regions.get(0).ready,"old snapshot retains its original targets/time");
   LocalRegionStability.Snapshot next=frame(r,b,11);
   ok(next.regions.size()==2&&next.regions.get(0).ready&&next.regions.get(1).count==1&&!next.regions.get(1).ready,"new target cannot inherit ready");
   r.configure(S,100,100,Arrays.asList(t("关闭",24)));
   ok(r.snapshotAt(captured)==a&&r.snapshotAt(next.sourceTimestampNs)==next,"changed and removed target do not erase source facts");
   LocalRegionStability.Snapshot changed=frame(r,b,12);
   ok(changed.regions.size()==1&&changed.regions.get(0).label.equals("关闭")&&changed.regions.get(0).count==1&&!changed.regions.get(0).ready,"changed target resets current state");
   r.configure(S,100,100,Collections.emptyList());
   ok(r.snapshotAt(captured)==a&&a.regions.size()==1,"lost target retains historical facts");
   r.configure("new-generation/task",100,100,Collections.emptyList());
   ok(r.snapshotAt(captured)==null,"scope changes still retire history");
 }

 public static void main(String[] args){Runnable[] tests={LocalRegionStabilityTest::asynchronousConfiguration,LocalRegionStabilityTest::tenFrames,LocalRegionStabilityTest::dynamicOutside,LocalRegionStabilityTest::targetChange,LocalRegionStabilityTest::surroundingChange,LocalRegionStabilityTest::duplicates,LocalRegionStabilityTest::fastFrames,LocalRegionStabilityTest::gapAndOrder,LocalRegionStabilityTest::epochs,LocalRegionStabilityTest::geometry,LocalRegionStabilityTest::jitterAndLost,LocalRegionStabilityTest::snapshots,LocalRegionStabilityTest::invalidBuffers,LocalRegionStabilityTest::alphaAndPosition,LocalRegionStabilityTest::limits,LocalRegionStabilityTest::exactDuration,LocalRegionStabilityTest::retainedHistory,LocalRegionStabilityTest::edgeAndStride,LocalRegionStabilityTest::invalidConfig,LocalRegionStabilityTest::clearAndNull};for(Runnable test:tests)test.run();System.out.println("PASS "+tests.length+" local source-region stability scenarios");}
}
